import {baseCase, scenarios, advisors, clone, AS_OF} from './lib/fixtures.js';
import {evaluate, calculatePortfolio} from './lib/engine.js';
import * as workflow from './lib/workflow.js';
import {taskGroups,taskQueue,filterTasks,sampleQuestion,sampleReply} from './lib/tasks.js';
import {runSuite} from './lib/acceptance.js';
import {references, estimateFees, nextQuestions, reportMarkup, reportDocument} from './lib/demo.js';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const fmt=n=>new Intl.NumberFormat('zh-CN').format(n);
let workspace,storageMessage='进度仅保存在此浏览器',restoreNotice='',recoveryBackup='',backupSaved=false,actionError='';
let savedWorkspace='';try{savedWorkspace=globalThis.localStorage?.getItem(workflow.STORAGE_KEY)||'';const recovery=workflow.recoverWorkspace(savedWorkspace);workspace=recovery.workspace;if(recovery.recovered.length){recoveryBackup=savedWorkspace;restoreNotice=`已恢复其他场景；${recovery.recovered.length} 个损坏场景已载入初始样例。原始记录可下载备份。`;}}catch{workspace=workflow.newWorkspace();recoveryBackup=savedWorkspace;restoreNotice='上次进度无法读取，已载入安全的初始场景。原始记录可下载备份。';}
let state=workspace.cases[workspace.active],tour=null,resetPending=false,queueFilter='open';
function persist(){try{if(!globalThis.localStorage)throw new Error();if(recoveryBackup&&!backupSaved){globalThis.localStorage.setItem(workflow.STORAGE_KEY+'-recovery-backup',recoveryBackup);backupSaved=true;}globalThis.localStorage.setItem(workflow.STORAGE_KEY,JSON.stringify(workspace));storageMessage='进度已保存在此浏览器';}catch{storageMessage='当前浏览器无法保存，刷新会丢失本次进度';}const el=$('#save-indicator');if(el)el.textContent=storageMessage;}
const nav=[['overview','◫','工作台概览'],['companion','◌','客户助手'],['copilot','◇','顾问工作台'],['evidence','▤','证据中心'],['references','↗','调研与设计依据'],['evaluation','✓','验收实验室'],['delivery','↗','项目交付']];
const names={context:'待补信息',evidence:'待核验证据',scope:'超出范围',review:'待人工复核',explain:'可直接解释'};
const color={context:'amber',evidence:'amber',scope:'red',review:'blue',explain:'green'};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function log(action,detail){workflow.audit(state,action,detail);persist();}
function changeCase(id,keepTour=false){captureInputs();if(!keepTour)tour=null;persist();state=workflow.switchCase(workspace,id);resetPending=false;render();}
function invalidate(reason='客户或资料已更新'){workflow.invalidateCase(state,reason);if(tour!==null&&tour>0&&tour<4)tour=decision().canDraft?1:0;}
function decision(){return evaluate(state.case,advisors.author);}
function badge(d){const f=workflow.flow(state);return `<span data-flow-badge class="pill ${['closed','approved'].includes(f.id)?'green':['blocked'].includes(f.id)?'red':['context','evidence','stale','returned','unsaved'].includes(f.id)?'amber':'blue'}">${escape(f.label)}</span>`;}
function intro(k,title,sub){return `<div class="page-intro"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="subline">${sub}</p></div><span class="intro-date">MONDAY, OCTOBER 26</span></div>`;}
function selector(){return `<select class="scenario-select" id="scenario" aria-label="选择合成演示场景">${scenarios.map(s=>`<option value="${s.id}" ${s.id===state.scenario?'selected':''}>${s.label} · ${workspace.cases[s.id]?workflow.flow(workspace.cases[s.id]).label:'未开始'}</option>`).join('')}</select>`;}
function taskBoard(){
  const tasks=taskQueue(workspace),visible=filterTasks(tasks,queueFilter),open=filterTasks(tasks).length;
  return `<section class="panel task-board" aria-label="顾问待办总览"><div class="panel-title"><div><h2>顾问待办总览</h2><p class="fine">${open} 个待办 · ${tasks.length-open} 个已完成 · 仅汇总已打开的演示案例</p></div><span class="tag">本浏览器进度</span></div><div class="task-filters" role="group" aria-label="按处理阶段筛选">${taskGroups.map(([id,label])=>`<button class="task-filter ${queueFilter===id?'selected':''}" data-task-filter="${id}" aria-pressed="${queueFilter===id}">${label}<span>${filterTasks(tasks,id).length}</span></button>`).join('')}</div>${visible.length?`<ol class="task-list">${visible.map(t=>`<li class="task-row" data-task-row="${t.id}"><div><div class="task-row-heading"><strong>${escape(t.title)}</strong><span class="pill ${t.group==='closed'?'green':t.group==='blocked'?'red':'blue'}">${escape(t.label)}</span></div><p class="task-question">${escape(t.question)}</p><small>${escape(t.caseId)}${t.version?` · V${t.version}`:''} · ${escape(t.description)}</small></div><button class="button small" data-resume-case="${t.id}">${escape(t.button)} →</button></li>`).join('')}</ol>`:`<div class="task-empty"><strong>${queueFilter==='open'?'当前没有待处理案例':'这个阶段暂无案例'}</strong><p>${queueFilter==='open'?'可查看已完成报告，或在下方选择新的演示场景。':'切换筛选即可查看其他案例；未打开的场景不会加入待办。'}</p></div>`}</section>`;
}

function followupComposer(c){
  const personal=['personalized','portfolio'].includes(c.task);
  return `<div class="followup-compose"><h3>还有疑问？</h3><p class="fine">选择追问方向，由演示流程分配下一步；不会发送给真实顾问。</p>${personal?'<div class="notice">当前为个人情况流程，新的答复仍需人工复核。</div>':`<label class="field">追问方向<select id="followup-kind"><option value="same" ${state.followupKind==='same'?'selected':''}>继续一般知识 / 产品事实解释</option><option value="personalized" ${state.followupKind==='personalized'?'selected':''}>涉及我的持仓或用钱计划 · 需要复核</option></select></label><p class="fine">涉及个人情况时，会重新确认授权、检查客户信息和资料。</p>`}<label class="field">补充问题<textarea id="followup-question" rows="3" maxlength="1000" placeholder="请描述本次想继续了解的问题">${escape(state.followupText)}</textarea></label><div class="actions" style="margin-top:12px"><button class="button" id="sample-question">填入示例问题</button><button class="button primary" id="request-followup">提交演示追问</button></div><p class="fine">示例只填入文字；请确认追问方向和内容后提交。</p></div>`;
}

function clientFollowup(){const q=state.case.followup;if(!q)return '';return `<div class="notice ${q.escalated?'amber':''}"><strong>当前追问${q.escalated?' · 已转为个人情况':''}</strong><p class="followup-question">${escape(q.question)}</p>${q.escalated?'请重新确认演示授权与客户信息，核对持仓和证据后，由顾问补充答复并复核。':'继续沿当前任务流程处理，上一轮交付已留档。'}</div>`;}
function steps(){const f=workflow.flow(state),general=['education','compare'].includes(state.case.task);const labels=general?['证据核验','一般解释交付','客户确认']:['信息检查','证据核验','草稿编辑','人工复核','客户交付','客户确认'];const phase=general?({blocked:0,context:0,evidence:0,ready:0,stale:0,followup:1,editing:1,unsaved:1,delivered:2,closed:3}[f.id]??0):({blocked:0,context:0,evidence:1,ready:2,stale:2,followup:2,editing:2,unsaved:2,returned:2,submitted:3,approved:4,delivered:5,closed:6}[f.id]??0);return `<div class="stepper">${labels.map((label,i)=>`<div class="step ${i<phase?'done':i===phase?'current':''}"><b>${i<phase?'✓':String(i+1).padStart(2,'0')}</b>${label}</div>`).join('')}</div>`;}

function reasons(){const d=decision();return d.reasons.length?d.reasons.map(r=>`<div class="reason"><span class="reason-message">${escape(r.message)}</span>${r.field?`<a class="text-link" href="#companion">返回客户信息补充 ↗</a>`:''}</div>`).join(''):`<div class="notice green">${d.canExplain?'当前资料可用于一般解释，无需个人画像或人工审批。':'必要条件已满足；个性化草稿仍需提交并完成人工复核。'}</div>`;}

function overview(){const d=decision();return intro('RESEARCH, WITH REASON','让每一步解释，都有依据。','先跟随三分钟导览走通完整流程，也可以自由切换八组演示场景。')+taskBoard()+`<section class="hero"><div><div class="hero-kicker">ADVISOR COPILOT × WEALTH COMPANION</div><h2>有上下文的理解<br>有证据的金融服务</h2><p>先知道信息是否足够，再判断结论是否有据。<br>体验一条可以追问、暂停、复核与追溯的完整服务流程。</p><div class="actions"><button class="button light" data-tour-start>三分钟引导演示 <span>↗</span></button><a class="button ghost" href="#evaluation">查看验收</a></div></div><div class="hero-art" aria-hidden="true"><div class="ring"></div><div class="ring inner"></div><div class="core">K</div><i class="orbit-dot"></i></div></section><div class="metrics"><div class="metric"><div class="metric-label">演示场景</div><div class="metric-value">08<small>组</small></div><div class="metric-note">覆盖正常路径与异常处理</div></div><div class="metric"><div class="metric-label">当前独立证据</div><div class="metric-value">${d.independentSources}<small>来源</small></div><div class="metric-note">转载资料仅计为同一来源</div></div><div class="metric"><div class="metric-label">当前待处理项</div><div class="metric-value">${d.reasons.length.toString().padStart(2,'0')}<small>项</small></div><div class="metric-note">信息与证据缺口共同保留</div></div><div class="metric"><div class="metric-label">本次模拟交付</div><div class="metric-value" style="font-size:23px">${state.receipt?'客户已确认':state.delivery?'待客户确认':'尚未交付'}</div><div class="metric-note">当前案例状态；客户确认阅读后完成</div></div></div><div class="grid-two"><section class="panel"><div class="panel-title"><h2>选择一条体验路径</h2><span>SYNTHETIC CASES</span></div>${scenarios.map(s=>`<button class="scenario-row" data-scenario="${s.id}"><div><strong>${s.label}</strong><small>${s.caption}${workspace.cases[s.id]?` · ${workflow.flow(workspace.cases[s.id]).label}`:' · 未开始'}</small></div><span class="scenario-icon">↗</span></button>`).join('')}</section><section class="panel"><div class="panel-title"><h2>可信流程的三个检查点</h2></div><div class="compact-list"><div class="compact-item"><span class="number">01</span><div><p>信息足够，再开始</p><small>按任务检查目标、期限与资金需求，通用问题不收集完整画像。</small></div></div><div class="compact-item"><span class="number">02</span><div><p>每个事实，回到来源</p><small>核对产品、时间和口径，暂停无法解决的冲突。</small></div></div><div class="compact-item"><span class="number">03</span><div><p>顾问复核，版本绑定</p><small>关键内容改变后，原审批立即失效。</small></div></div></div></section></div>`;}
function field(label,name,value,type='text',full=false){const error=decision().reasons.find(r=>r.field===name);return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${escape(value??'')}" ${type==='number'?'step="1" min="0"':''} ${error?'aria-invalid="true"':''}>${error?`<small class="field-error">${escape(error.message)}</small>`:''}</label>`;}
function companion(){const c=state.case,p=state.pendingProfile??c.profile??{},d=decision(),blocked=d.states.includes('scope')&&!d.reasons.some(r=>r.code==='CONSENT_REQUIRED');return intro('WEALTH COMPANION','先理解你的问题','补充必要信息，接收经过流程检查的解释，确认阅读后完成本次案例。')+`<div class="actions" style="margin-bottom:20px">${selector()}${badge(d)}</div>${steps()}${blocked?`<section class="panel">${reasons()}<a class="button" href="#overview">选择其他演示场景</a></section>`:`<div class="grid-two"><div><section class="panel"><div class="client-chip"><span class="avatar">客</span><div>${escape(c.client)}<div class="fine">${escape(c.id)} · 合成客户</div></div></div><p class="question">“${escape(c.question)}”</p>${clientFollowup()}<div class="notice">${c.task==='education'?'这是通用知识问题，无需提供资产、期限或风险画像。':'先核对本次任务所需的信息与资料，再进入相应解释流程。'}</div>${['personalized','portfolio'].includes(c.task)?`<form id="profile-form"><div class="form-grid">${field('投资目标','goal',p.goal,'text',true)}${field('投资期限（月）','horizonMonths',p.horizonMonths,'number')}${field('最近用钱时间（月后）','liquidityMonths',p.liquidityMonths,'number')}${field('可承受损失比例（%）','riskCapacity',p.riskCapacity,'number')}${field('资金不可动用期限（月）','lockMonths',p.lockMonths,'number')}<label class="field full">风险偏好<select name="riskPreference"><option value="">请选择</option>${['低','中等','高'].map(v=>`<option ${v===p.riskPreference?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="checkbox"><input name="consent" type="checkbox" ${(state.pendingProfile?state.pendingProfile.consent:c.consent)?'checked':''}>确认使用本次合成客户资料进行演示</label><p class="fine" id="profile-dirty">${state.pendingProfile?'有客户信息修改待保存，保存后重新检查。':'信息变更会使旧草稿和审批失效。'}</p><div class="actions" style="margin-top:14px"><button class="button primary" type="submit">保存并重新检查</button><button class="button" type="button" id="sample-profile">填入合成示例信息</button><button class="button" type="button" id="discard-profile">放弃未保存修改</button><button class="button" type="button" id="refresh-holdings">载入有效合成快照</button></div></form>`:''}<div class="actions" style="margin-top:18px">${state.draft?'<a class="button" href="#copilot">继续处理当前草稿 →</a>':`<button class="button primary" id="generate" ${(!d.canDraft&&!d.canExplain)||workflow.hasUnsaved(state)||workflow.needsReply(state)?'disabled':''}>${d.canExplain?'生成并交付一般解释':'生成顾问草稿'} →</button>`}</div></section>${state.delivery?`<section class="panel"><div class="panel-title"><h2>已收到的解释</h2><span class="pill green">V${state.delivery.version}</span></div><div class="draft-text delivery-quote">${escape(state.delivery.body)}</div><div class="notice ${state.receipt?'green':''}">${state.receipt?'你已确认阅读。本次案例已完成。':'请阅读本次解释。确认仅表示已阅读演示内容，不代表同意任何交易或投资安排。'}</div><div class="actions"><button class="button primary" id="acknowledge" ${state.receipt||workflow.hasUnsaved(state)?'disabled':''}>${state.receipt?'已确认阅读':'确认已阅读'}</button><a class="button" href="#delivery">查看完整报告</a></div>${followupComposer(c)}</section>`:''}</div><div><section class="panel"><div class="panel-title"><h2>当前处理状态</h2></div>${badge(d)}<div class="state-summary">${escape(workflow.flow(state).label)}</div>${reasons()}</section>${portfolioCard()}</div></div>`}`;}

function portfolioCard(){if(decision().states.includes('scope'))return '';try{const v=calculatePortfolio(state.case);return `<section class="panel"><div class="panel-title"><h2>合成持仓快照</h2><span>¥${fmt(v.total)}</span></div>${v.rows.map(r=>`<div style="margin-bottom:18px"><div style="display:flex;justify-content:space-between;font-size:12px;gap:10px"><span>${escape(r.name)}</span><span>${(r.weight*100).toFixed(1)}%</span></div><div class="bar"><i style="width:${r.weight*100}%"></i></div></div>`).join('')}<p class="fine">快照：${escape(state.case.holdings.asOf)}<br>计算：单项金额 ÷ 总金额；均为人民币。<br>产品数量不能证明已经分散风险，仍需核对底层资产与行业重叠。<a class="text-link" href="#references">查看概念来源 R3 ↗</a></p></section>`;}catch{return '';}}
function copilot(){const d=decision(),draft=state.draft,f=workflow.flow(state),general=['education','compare'].includes(state.case.task),submitted=state.reviewStatus==='submitted'&&f.id==='submitted';return intro('ADVISOR COPILOT','把草稿、复核与交付衔接起来','保存修改 → 提交复核 → 批准或退回 → 交付。资料变更时明确提示重新起草。')+`<div class="actions" style="margin-bottom:20px">${selector()}${badge(d)}<span class="tag">起草：林顾问 / 复核：陈复核</span></div>${steps()}<div class="grid-two"><div><section class="panel"><div class="panel-title"><h2>解释草稿</h2>${draft?`<span class="tag">V${draft.version}</span>`:''}</div>${followupCard()}${meetingBrief()}${draft?`${f.id==='stale'?'<div class="notice amber">这份草稿依据的是旧资料，仅供参考。点击“重新生成”更新引用与客户信息。</div>':''}${state.reviewNote?`<div class="notice ${state.reviewStatus==='returned'?'amber':''}"><strong>${state.reviewStatus==='returned'?'退回意见':'最近复核意见'}</strong><br>${escape(state.reviewNote)}</div>`:''}<label class="field">${workflow.needsReply(state)?'上一轮正文 · 补充答复后生成新稿':'编辑正文'}<textarea class="draft-editor" id="draft-body" ${workflow.needsReply(state)?'readonly':''}>${escape(state.editorText??draft.body)}</textarea></label><p class="fine" id="draft-dirty">${workflow.hasUnsaved(state)?'有修改待保存。':'正文已保存。修改后需要重新提交复核。'}</p><div class="actions" style="margin-top:15px"><button class="button" id="save-draft">保存草稿修改</button><button class="button" id="discard-draft">放弃未保存修改</button><button class="button" id="generate" ${(!d.canDraft&&!d.canExplain)||workflow.hasUnsaved(state)||workflow.needsReply(state)?'disabled':''}>重新生成</button></div>${!general?`<div class="actions" style="margin-top:15px"><button class="button primary" id="submit" ${!['editing','returned'].includes(f.id)||workflow.unchangedReturn(state)?'disabled':''}>提交人工复核</button><span class="fine">${f.id==='submitted'?'当前版本已提交，等待复核。':f.id==='approved'?'已批准，可以交付。':'每次修改或重建后，按新版本提交。'}</span></div>`:''}`:`<div class="empty"><b>当前还没有草稿</b>${escape(f.description)}<br><button style="margin-top:20px" class="button primary" id="generate" ${!d.canDraft&&!d.canExplain?'disabled':''}>生成解释草稿</button></div>`}<p class="fine" style="margin-top:16px">确定性模板 · 合成资料 · 未接入真实大模型</p></section>${draft?`<section class="panel"><div class="panel-title"><h2>草稿引用</h2><a class="text-link" href="#evidence">核对当前资料 ↗</a></div>${draft.citations.map(e=>`<div class="reason">[${escape(e.id)}] ${escape(e.title)}<div class="fine">${escape(e.section)} · V${escape(e.version)}</div></div>`).join('')}</section>`:''}</div><div><section class="panel"><div class="panel-title"><h2>${general?'一般解释交付':'人工复核'}</h2>${badge(d)}</div>${general?`<div class="notice">此任务不需要个性化审批。${state.delivery?'一般解释已交付，可返回客户端确认阅读。':'保存正文后可以直接交付。'}</div><button class="button primary" id="deliver" ${!draft||workflow.hasUnsaved(state)||!d.canExplain||f.id==='stale'||Boolean(state.delivery)?'disabled':''}>交付一般解释</button>`:`<div class="review-role">陈复核 · 与起草人不同的演示角色</div><label class="field">复核或退回意见<textarea id="review-note" rows="4" placeholder="指出已核对内容，或说明需要修改的地方">${escape(state.reviewFormNote)}</textarea></label><label class="checkbox"><input id="review-check" type="checkbox" ${state.reviewFormChecked?'checked':''}>已检查客户信息、引用及解释边界</label><div class="actions"><button class="button primary" id="approve" ${!submitted?'disabled':''}>批准当前版本</button><button class="button" id="return-draft" ${!submitted?'disabled':''}>退回修改</button></div><p class="fine" style="margin-top:12px">退回必须填写意见；修改并重新提交后才能审批。</p><div class="actions" style="margin-top:20px"><button class="button primary" id="deliver" ${f.id!=='approved'?'disabled':''}>交付获批版本</button>${state.delivery?'<a class="button" href="#companion">转到客户确认 →</a>':''}</div>`}</section><section class="panel"><div class="panel-title"><h2>条件检查</h2></div>${reasons()}</section></div></div>`;}

function evidence(){const d=decision(),c=state.case;return intro('EVIDENCE CENTER','让事实可以被逐项核对','相同指标先对齐时间、单位与口径，转载资料不重复计为独立来源。')+`<div class="actions" style="margin-bottom:22px">${selector()}${badge(d)}</div><div class="grid-two"><section class="panel"><div class="panel-title"><h2>本次任务证据</h2><span>${d.independentSources} 个独立来源</span></div>${d.states.includes('scope')?'<div class="empty">当前请求没有资料访问权限。</div>':c.evidence.map(e=>`<article class="evidence-card"><div class="source-card-top"><span class="source-id">${escape(e.id)} · ${escape(e.origin)}</span><span class="tag">合成资料 ${e.quarantined?'· 已隔离':''}</span></div><h3>${escape(e.title)}</h3><p>${escape(e.snippet)}</p><div class="source-meta">${escape(e.section)} · 版本 ${escape(e.version)}<br>发布：${escape(e.publishedAt)} / 适用期间：${escape(e.period)}<br>指标：${escape(e.metric)} / 值：${escape(e.value)} ${escape(e.unit)}</div></article>`).join('')}</section><div>${feeCard()}<section class="panel"><div class="panel-title"><h2>证据检查</h2></div>${reasons()}<div class="actions" style="margin-top:18px"><button class="button primary" id="restore-evidence" ${d.states.includes('scope')?'disabled':''}>恢复合成基准资料</button><button class="button" id="fail-retrieval" ${d.states.includes('scope')?'disabled':''}>模拟检索失败</button><button class="button" id="change-version" ${d.states.includes('scope')?'disabled':''}>模拟来源版本更新</button></div><p class="fine" style="margin-top:15px">恢复按钮只是载入内置样例，不代表进行了真实外部核验。更新来源版本会使旧草稿无法交付。</p></section><section class="panel"><h2>可信资料的最小记录</h2><div class="compact-list" style="margin-top:22px">${['来源身份与独立性','产品、指标、期间与单位','原文位置与资料版本','事实与引用的一一对应'].map((t,i)=>`<div class="compact-item"><span class="number">0${i+1}</span><p>${t}</p></div>`).join('')}</div></section></div></div>`;}
function evaluation(){const r=state.report;return intro('ACCEPTANCE LAB','用失败场景检验流程','运行与本地测试相同的规则验收集，结果来自当前执行。')+`<div class="actions" style="margin-bottom:24px"><button class="button primary" id="run-tests">运行规则验收 ↗</button>${r?`<button class="button" id="export-tests">下载测试结果</button><span class="fine">执行时间：${escape(new Date(r.timestamp).toLocaleString('zh-CN'))}</span>`:''}</div>${r?`<div class="metrics"><div class="metric"><div class="metric-label">测试通过</div><div class="metric-value">${r.passed}<small>/ ${r.total}</small></div><div class="metric-note">合成规则与状态测试</div></div><div class="metric"><div class="metric-label">失败用例</div><div class="metric-value">${r.failed}</div><div class="metric-note">逐例保留结果</div></div><div class="metric"><div class="metric-label">测试覆盖原始场景</div><div class="metric-value">14<small>类</small></div><div class="metric-note">并扩展输入与审批边界</div></div><div class="metric"><div class="metric-label">模型回答质量</div><div class="metric-value" style="font-size:23px">未评测</div><div class="metric-note">未连接模型，不推算得分</div></div></div><section class="panel"><div class="panel-title"><h2>本次执行结果</h2><span>POLICY ${escape(r.policy)}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>编号</th><th>验收条件</th><th>结果</th></tr></thead><tbody>${r.results.map(t=>`<tr><td>${escape(t.id)}</td><td>${escape(t.name)}${t.error?`<div class="fine">${escape(t.error)}</div>`:''}</td><td class="table-status"><span class="pill ${t.passed?'green':'red'}">${t.passed?'通过':'失败'}</span></td></tr>`).join('')}</tbody></table></div></section>`:'<div class="empty"><b>准备好测试 14 类关键行为</b>包含缺失信息、来源冲突、过期资料、跨机构请求与审批失效。<br>点击“运行规则验收”产生真实的本次测试结果。</div>'}<div class="notice amber">测试对象是确定性规则原型。测试通过不表示生产身份认证、真实资料核验、模型质量或金融合规已经完成验证。</div>`;}
function reportWithRecord(r){return {...r.report,recordStatus:r.status,deliveryId:r.id,deliveredAt:r.createdAt,acknowledgedAt:r.receipt?.confirmedAt};}
function delivery(){const record=state.deliveries.find(r=>r.id===state.delivery?.id),f=workflow.flow(state);return intro('DELIVERY & HANDOFF','交付、确认与历史记录','已交付版本独立保存。后续资料或草稿变化时，旧记录仍可追溯。')+`<div class="grid-two"><div><section class="panel"><div class="panel-title"><h2>当前交付报告</h2>${badge(decision())}</div>${record?`${reportMarkup(reportWithRecord(record))}<div class="receipt-box"><strong>${record.receipt?'客户已确认阅读':'等待客户确认阅读'}</strong><p>${record.receipt?escape(new Date(record.receipt.confirmedAt).toLocaleString('zh-CN')):'到客户助手完成最后一步，本案例即结束。'}</p></div><div class="actions" style="margin-top:20px"><button class="button primary" id="export-report">下载报告 HTML</button><button class="button" id="print-report">打印 / 保存 PDF</button><button class="button" id="export-delivery">下载交付记录</button><a class="button" href="#companion">${state.receipt?'查看客户端':'前往客户确认'} →</a></div>`:`<div class="empty"><b>${state.deliveries.length?'当前资料或草稿已变更':'还没有本案例的交付'}</b>${escape(f.description)}<br><a href="#${f.route}" class="button" style="margin-top:15px">${escape(f.button)} →</a></div>`}</section><section class="panel"><div class="panel-title"><h2>本案例交付历史</h2><span>最近 20 份</span></div>${state.deliveries.length?state.deliveries.map(r=>`<div class="history-row"><div><strong>V${r.version} · ${r.status==='current'?'当前版本':'历史版本'}</strong><small>${escape(new Date(r.createdAt).toLocaleString('zh-CN'))} · ${r.receipt?'客户已确认':'未确认'}</small><p class="fine">${r.status==='superseded'?'后续内容已变化；此文件仅为当时交付记录。':'本次交付对应的固定版本。'}</p></div><button class="button small" data-export-history="${escape(r.id)}">下载当时报告</button></div>`).join(''):'<p class="fine">交付后出现记录；反复点击交付不会重复生成同一版本。</p>'}</section><div class="doc-grid"><a class="doc-link" href="./guide.html" target="_blank" rel="noopener"><strong>项目说明与交接手册 ↗</strong><p>当前功能、演示边界与使用方式。</p></a><a class="doc-link" href="./demo.html" target="_blank" rel="noopener"><strong>演示脚本与答辩材料 ↗</strong><p>三分钟主流程与异常分支。</p></a></div></div><section class="panel"><div class="panel-title"><h2>本案例操作轨迹</h2><button class="icon-btn" id="export-audit">导出</button></div><p class="fine" style="margin-bottom:20px">${escape(storageMessage)}。保留最近 100 条操作；演示记录可修改，不是生产审计日志。</p>${state.audit.length?state.audit.map(a=>`<div class="audit-entry"><time>${escape(new Date(a.time).toLocaleString('zh-CN'))}</time><strong>${escape(a.action)}</strong><div class="fine">${escape(a.detail)}</div></div>`).join(''):'<div class="empty">本案例尚无操作</div>'}</section></div>`;}

function startTour(){changeCase('missing');const f=workflow.flow(state);tour=({context:0,blocked:0,ready:1,evidence:1,stale:2,followup:2,editing:2,returned:2,submitted:2,approved:2,delivered:3,closed:3,unsaved:state.pendingProfile?0:2}[f.id]??0);location.hash=tour===0?'companion':tour===1?'evidence':tour===2?'copilot':state.receipt?'delivery':'companion';render();toast('导览已从保存的进度继续；需要重演可重置本案例。');}
function tourPanel(){
  if(tour===null)return '';
  const guide=[
    ['01 / 05 · 补齐信息','将投资期限填写为 24 个月，点击“保存并重新检查”。向观众说明：缺少关键条件时先追问。','companion','下一步：查看证据',decision().canDraft],
    ['02 / 05 · 核对证据','查看两条合成资料，试算同为 10 万元、12 个月的管理费：300 元与 800 元。这里只比较管理费。','evidence','下一步：生成草稿',decision().canDraft],
    ['03 / 05 · 人工复核','阅读会前摘要和草稿，先提交人工复核，再填写意见、勾选检查并批准。也可以先退回修改。','copilot','下一步：交付报告',Boolean(state.draft?.approval)],
    ['04 / 05 · 客户确认与报告','展示客户沟通报告及待确认事项，请先到客户助手确认阅读，再查看报告。下一步切换冲突样例，当前交付会保留。',state.receipt?'delivery':'companion','下一步：查看冲突样例',Boolean(state.receipt)],
    ['05 / 05 · 展示暂停机制','同一产品费率同时出现 0.30% 与 0.60%，系统暂停费用比较与生成。点击“恢复合成基准资料”可演示恢复。','evidence','完成导览',true]
  ][tour];
  return `<section class="demo-guide" aria-label="三分钟演示导览"><div><div class="eyebrow">${guide[0]}</div><p>${guide[1]}</p><div class="tour-dots" aria-hidden="true">${[0,1,2,3,4].map(i=>`<i class="${i<=tour?'filled':''}"></i>`).join('')}</div></div><div class="guide-actions"><button class="button primary" id="tour-next" ${guide[4]?'':'disabled'}>${guide[3]}</button><a class="text-link" href="#${guide[2]}">回到当前步骤</a><div><button class="icon-btn" id="tour-restart">重置本案例</button><button class="icon-btn" id="tour-exit">退出导览</button></div></div></section>`;
}
function nextTour(){captureInputs();if(tour===0){if(!decision().canDraft||workflow.hasUnsaved(state))throw new Error('请先保存完整客户信息');tour=1;location.hash='evidence';}else if(tour===1){workflow.generate(state);tour=2;location.hash='copilot';}else if(tour===2){workflow.deliver(state);tour=3;location.hash='companion';}else if(tour===3){if(!state.receipt)throw new Error('请先由客户确认阅读');changeCase('conflict',true);tour=4;location.hash='evidence';}else{tour=null;toast('导览完成，各场景进度已保留');}render();window.scrollTo(0,0);}

function followupCard(){const q=state.case.followup;if(!q)return '';return `<section class="followup-card"><div class="panel-title"><h3>${q.reply?'本轮追问与补充答复':'客户有新的追问'}</h3><span class="tag">来自 ${escape(q.fromDelivery)}</span></div><p class="question">“${escape(q.question)}”</p>${q.reply?`<p class="draft-text">${escape(q.reply)}</p><p class="fine">补充答复已进入当前版本，按此任务的原有审核流程交付。</p>`:`<label class="field">顾问补充答复<textarea id="followup-reply" rows="4" maxlength="4000" placeholder="根据现有资料补充说明；资料不足时明确还需确认什么。">${escape(state.replyText)}</textarea></label><p class="fine">可填入演示示例再修改，不会调用真实模型。保存后重建草稿，个性化内容仍需重新审批。</p><div class="actions" style="margin-top:12px"><button class="button" id="sample-reply">填入示例答复</button><button class="button primary" id="answer-followup">保存答复并重建草稿</button></div>`}</section>`;}
function meetingBrief(){
  if(decision().states.includes('scope'))return '<div class="notice amber">当前请求超出处理范围。</div>';
  const c=state.case,p=c.profile;
  return `<details class="meeting-brief" open><summary>会前摘要与沟通重点</summary><p>${escape(c.question)}</p>${c.task==='personalized'?`<div class="brief-grid"><div><small>目标</small>${escape(p.goal||'待确认')}</div><div><small>计划 / 用钱时间</small>${escape(p.horizonMonths??'待确认')} 个月 / ${escape(p.liquidityMonths??'待确认')} 个月后</div></div>`:''}<strong>下一步仍需确认</strong><ul>${nextQuestions(c).map(q=>`<li>${escape(q)}</li>`).join('')}</ul><span class="fine">根据本次结构化资料整理，不代表已完成真实会谈或适当性评估。</span></details>`;
}
function feeCard(){
  if(['education','execute'].includes(state.case.task)||decision().states.includes('scope'))return '';
  let r;try{r=estimateFees(state.case,advisors.author,state.fee.principal,state.fee.months);}catch(e){return `<section class="panel"><div class="panel-title"><h2>同金额管理费比较</h2><span class="pill amber">已暂停</span></div><p class="fine">${escape(e.message)}</p></section>`;}
  return `<section class="panel fee-panel"><div class="panel-title"><h2>同金额管理费比较</h2><span class="tag">合成测算</span></div><form id="fee-form"><div class="form-grid">${field('每项比较金额（元）','principal',r.principal,'number')}${field('比较期限（月）','months',r.months,'number')}</div><button class="button small" type="submit" style="margin-top:12px">重新计算</button></form><div class="fee-results" aria-live="polite">${r.rows.map(x=>`<div><span>示例产品 ${escape(x.product)} · ${x.rate.toFixed(2)}% / 年</span><b>¥${fmt(x.cost)}</b><small>[${escape(x.citation)}] · ${escape(r.period)}</small></div>`).join('')}</div><div class="fee-difference">同金额、同期管理费差额 <strong>¥${fmt(r.difference)}</strong></div><p class="fine">公式：比较金额 × 年管理费率 × 月数 ÷ 12。假设比较金额和费率不变；实际计费基数可能随净值变化。<br>未包含申购、赎回、托管、销售服务等费用，不代表总成本。A、B 为不同类型的虚构产品，不能仅凭费用选择。<a class="text-link" href="#references">参考 R2、R4 ↗</a></p></section>`;
}
function research(){return intro('RESEARCH NOTES','每项补充，都能找到来处','公开资料提供设计参考；演示中的客户、产品和费率仍是合成样例。')+`<div class="notice">检索整理：2026 年 10 月 26 日。下列为人工整理的官方公开资料，不属于自动检索结果，也未被用作虚构产品费率的证据。英文资料的概念解释不等同于中国监管要求。</div><div class="research-grid">${references.map(r=>`<article class="panel reference-card"><div class="source-card-top"><span class="source-id">${r.id}</span><span class="tag">官方公开资料</span></div><h2>${escape(r.title)}</h2><p class="reference-publisher">${escape(r.publisher)} · ${escape(r.date)}</p><p>${escape(r.summary)}</p><div class="reference-use"><small>本 DEMO 的设计取舍</small>${escape(r.application)}</div><a class="button small" href="${escape(r.url)}" target="_blank" rel="noopener noreferrer">查看原始网页 ↗</a></article>`).join('')}</div><section class="panel"><h2>适合现场讲清楚的三件事</h2><div class="compact-list" style="margin-top:20px">${['客户信息不足时，解释为什么需要补充。','同一事实有冲突时，暂停依赖它的计算与草稿。','交付包含引用、复核记录和下一步沟通问题。'].map((t,i)=>`<div class="compact-item"><span class="number">0${i+1}</span><p>${t}</p></div>`).join('')}</div></section>`;}
function downloadFile(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function download(name,data){const b=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function safe(action){actionError='';const box=$('#action-error');if(box){box.hidden=true;box.textContent='';}try{action();}catch(e){actionError=e.message;if(box){box.hidden=false;box.textContent=e.message;}persist();toast(e.message);}}

function profileValues(form){const data=new FormData(form),p={};for(const k of ['goal','riskPreference'])p[k]=data.get(k);for(const k of ['horizonMonths','liquidityMonths','riskCapacity','lockMonths']){const v=data.get(k);p[k]=v===''?null:Number(v);}p.consent=data.has('consent');return p;}
function captureInputs(){
  const form=$('#profile-form');if(form){const p=profileValues(form);state.pendingProfile=Object.keys(p).some(k=>p[k]!== (k==='consent'?state.case.consent:state.case.profile[k]))?p:null;}
  if($('#followup-kind'))state.followupKind=$('#followup-kind').value;
  if($('#followup-question'))state.followupText=$('#followup-question').value;
  if($('#followup-reply'))state.replyText=$('#followup-reply').value;
  const body=$('#draft-body');if(body&&state.draft)state.editorText=body.value;
  if($('#review-note'))state.reviewFormNote=$('#review-note').value;
  if($('#review-check'))state.reviewFormChecked=$('#review-check').checked;
}
function syncControls(){
  const f=workflow.flow(state),d=f.decision,dirty=workflow.hasUnsaved(state),personal=d.canDraft;
  const allowed={'sample-question':!state.followupText.trim(),'sample-reply':!state.replyText.trim(),generate:(d.canDraft||d.canExplain)&&!dirty&&!workflow.needsReply(state),submit:['editing','returned'].includes(f.id)&&personal&&!workflow.unchangedReturn(state),approve:f.id==='submitted','return-draft':f.id==='submitted',deliver:f.id==='approved'||(d.canExplain&&f.id==='editing'),acknowledge:f.id==='delivered','save-draft':Boolean(state.draft)&&!workflow.needsReply(state),'request-followup':Boolean(state.delivery)&&!dirty,'answer-followup':workflow.needsReply(state)&&!dirty&&(d.canDraft||d.canExplain),'tour-next':!dirty&&(tour===0||tour===1?d.canDraft:tour===2?f.id==='approved':tour===3?Boolean(state.receipt):tour===4)};
  for(const [id,enabled]of Object.entries(allowed))if($('#'+id))$('#'+id).disabled=!enabled;
  if($('#flow-label'))$('#flow-label').textContent=f.label;if($('#flow-description'))$('#flow-description').textContent=f.description;if($('#flow-action'))$('#flow-action').textContent=f.button;
  document.querySelectorAll('[data-flow-badge]').forEach(el=>{el.textContent=f.label;el.className='pill '+(['closed','approved'].includes(f.id)?'green':['blocked'].includes(f.id)?'red':['context','evidence','stale','returned','unsaved','followup'].includes(f.id)?'amber':'blue');});
}
function dirtyUpdate(){captureInputs();persist();const dirty=workflow.hasUnsaved(state);syncControls();if($('#draft-dirty'))$('#draft-dirty').textContent=dirty?'有修改待保存，保存前不能继续审批或交付。':'正文与已保存版本一致。';if($('#profile-dirty'))$('#profile-dirty').textContent=state.pendingProfile?'有客户信息修改待保存。':'信息与已保存版本一致。';}
function generateAction(){workflow.generate(state);if(tour===0||tour===1)tour=2;if(decision().canExplain){workflow.deliver(state);location.hash='companion';toast('一般解释已交付，请确认阅读');}else{location.hash='copilot';toast('草稿已生成，请编辑并提交复核');}}
const actions={
  'request-followup':()=>{workflow.requestFollowup(state,state.followupText,state.followupKind);tour=null;location.hash=workflow.flow(state).route;toast(state.case.followup.escalated?'已转为个人情况，请先重新确认授权与客户信息':'追问已进入顾问待办，旧交付已留档');},
  'sample-question':()=>{if(state.followupText.trim())throw new Error('已有追问内容，请先清空后再填入示例。');state.followupText=sampleQuestion(state);toast('示例已填入，请确认方向和文字后提交');},
  'sample-reply':()=>{if(state.replyText.trim())throw new Error('已有答复内容，请先清空后再填入示例。');state.replyText=sampleReply(state);toast('示例答复已填入，可编辑后保存；尚未提交复核');},
  'sample-profile':()=>{const p=baseCase.profile,consent=state.pendingProfile?.consent??state.case.consent;state.pendingProfile=Object.fromEntries(['goal','horizonMonths','liquidityMonths','riskCapacity','lockMonths','riskPreference'].map(k=>[k,p[k]]));state.pendingProfile.consent=consent;toast('已填入合成示例信息，请确认授权后保存');},
  'answer-followup':()=>{workflow.answerFollowup(state,state.replyText);toast('补充答复已写入新版草稿，请按当前流程复核或交付');},
  'recovery-download':()=>downloadFile('kingstar-recovery-backup.json',recoveryBackup,'application/json'),
  'recovery-dismiss':()=>{restoreNotice='';},
  generate:generateAction,
  submit:()=>{workflow.submit(state);toast('已提交，等待陈复核处理');},
  'save-draft':()=>{workflow.saveDraft(state,$('#draft-body').value);toast('正文已保存，请按当前状态继续');},
  'discard-draft':()=>{state.editorText=state.draft.body;toast('已放弃未保存的正文修改');},
  'discard-profile':()=>{state.pendingProfile=null;toast('已放弃未保存的客户信息修改');},
  approve:()=>{workflow.review(state,'approve',state.reviewFormNote,state.reviewFormChecked);toast('当前版本已批准，可以交付');},
  'return-draft':()=>{workflow.review(state,'return',state.reviewFormNote);toast('已退回，请修改正文后重新提交');},
  deliver:()=>{workflow.deliver(state);if(tour!==null)tour=3;location.hash='companion';toast('解释已交付，请在客户端确认阅读');},
  acknowledge:()=>{workflow.acknowledge(state);location.hash='delivery';toast('客户已确认，本次案例已完成');},
  'refresh-holdings':()=>{state.case.holdings=clone(baseCase.holdings);invalidate('载入有效合成持仓快照');},
  'restore-evidence':()=>{state.case.evidence=state.case.task==='education'?scenarios.find(s=>s.id==='education').make().evidence:clone(baseCase.evidence);state.case.retrieval='ok';invalidate('恢复合成基准资料，非外部核验');},
  'fail-retrieval':()=>{state.case.retrieval='failed';invalidate('模拟检索失败');},
  'change-version':()=>{state.case.evidence[0].version=String(Number(state.case.evidence[0].version)+1);invalidate('来源版本更新，旧草稿需重新生成');},
  'run-tests':()=>{state.report=runSuite();log('运行规则验收',`${state.report.passed}/${state.report.total} 通过`);toast(`验收完成：${state.report.passed}/${state.report.total} 通过`);},
  'tour-next':nextTour,'tour-exit':()=>{tour=null;},'tour-restart':()=>{tour=null;resetPending=true;},
  'export-report':()=>{const r=state.deliveries.find(x=>x.id===state.delivery?.id);if(!r)throw new Error('当前没有交付报告');downloadFile('kingstar-client-report.html',reportDocument(reportWithRecord(r)),'text/html;charset=utf-8');log('导出沟通报告',`V${r.version}`);},
  'print-report':()=>{if(!state.delivery)throw new Error('当前没有交付报告');window.print();},
  'export-tests':()=>download('kingstar-acceptance-results.json',state.report),
  'export-audit':()=>download('kingstar-demo-trace.json',{synthetic:true,audit:state.audit}),
  'export-delivery':()=>download('kingstar-delivery.json',{synthetic:true,delivery:state.delivery,receipt:state.receipt,audit:state.audit}),
  'reset-cancel':()=>{resetPending=false;},
  'reset-confirm':()=>{const id=state.scenario;state=workflow.newCase(id);workspace.cases[id]=state;tour=null;resetPending=false;log('重置当前案例','仅清空本案例，其他场景进度保留');toast('本案例已重置');},
  'next-case':()=>{changeCase(scenarios[(scenarios.findIndex(x=>x.id===state.scenario)+1)%scenarios.length].id);location.hash='companion';}
};
function bind(){
  document.querySelectorAll('[data-task-filter]').forEach(b=>b.onclick=()=>safe(()=>{captureInputs();queueFilter=b.dataset.taskFilter;render();}));
  document.querySelectorAll('[data-resume-case]').forEach(b=>b.onclick=()=>safe(()=>{changeCase(b.dataset.resumeCase);location.hash=workflow.flow(state).route;render();}));
  document.querySelectorAll('[data-tour-start]').forEach(el=>el.onclick=startTour);
  document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{changeCase(b.dataset.scenario);location.hash='companion';render();});
  document.querySelectorAll('[data-export-history]').forEach(b=>b.onclick=()=>safe(()=>{const r=state.deliveries.find(x=>x.id===b.dataset.exportHistory);downloadFile(`kingstar-report-${r.id}.html`,reportDocument(reportWithRecord(r)),'text/html;charset=utf-8');}));
  if($('#scenario'))$('#scenario').onchange=e=>changeCase(e.target.value);
  const form=$('#profile-form');if(form){form.oninput=dirtyUpdate;form.onchange=dirtyUpdate;form.onsubmit=e=>{e.preventDefault();safe(()=>{captureInputs();if(state.pendingProfile){const {consent,...p}=state.pendingProfile;Object.assign(state.case.profile,p,{confirmedAt:AS_OF,validUntil:'2026-11-25'});state.case.consent=consent;state.pendingProfile=null;invalidate('客户信息已保存并重新检查');}render();toast('客户信息已检查');});};}
  if($('#draft-body'))$('#draft-body').oninput=dirtyUpdate;
  for(const id of ['review-note','review-check','followup-question','followup-reply'])if($('#'+id))$('#'+id).oninput=()=>{captureInputs();persist();syncControls();};
  if($('#followup-kind'))$('#followup-kind').onchange=()=>{captureInputs();persist();};
  const feeForm=$('#fee-form');if(feeForm)feeForm.onsubmit=e=>{e.preventDefault();safe(()=>{const data=new FormData(feeForm),principal=Number(data.get('principal')),months=Number(data.get('months'));estimateFees(state.case,advisors.author,principal,months);state.fee={principal,months};log('比较合成管理费',`同额 ¥${principal}，${months} 个月`);render();});};
  for(const [id,fn]of Object.entries(actions)){const el=$('#'+id);if(el)el.onclick=()=>safe(()=>{captureInputs();fn();render();});}
  syncControls();
  if($('#flow-action'))$('#flow-action').onclick=()=>safe(()=>{captureInputs();const f=workflow.flow(state);if(location.hash.slice(1)!==f.route){location.hash=f.route;render();}else if(f.action){actions[f.action]();render();}else{location.hash=f.route;render();}});
}
function flowPanel(){const f=workflow.flow(state);return `<section class="flow-guide"><div><span class="eyebrow">当前案例 · ${escape(state.case.id)}</span><h2 id="flow-label">${escape(f.label)}</h2><p id="flow-description">${escape(f.description)}</p></div><div class="actions"><button class="button primary" id="flow-action">${escape(f.button)}</button>${f.id==='closed'?'<button class="button" id="next-case">体验下一场景 →</button>':''}</div></section>`;}
function render(){const id=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'overview';$('#navigation').innerHTML=nav.map(([key,symbol,title])=>`<a href="#${key}" class="nav-link ${key===id?'active':''}" ${key===id?'aria-current="page"':''}><span class="nav-symbol">${symbol}</span>${title}</a>`).join('');$('#view-title').textContent=nav.find(n=>n[0]===id)[2];$('#main').innerHTML=`<div class="notice amber action-error" id="action-error" role="alert" ${actionError?'':'hidden'}>${escape(actionError)}</div>`+(restoreNotice?`<div class="notice amber">${escape(restoreNotice)}<div class="actions"><button class="button small" id="recovery-download">下载原始进度备份</button><button class="button small" id="recovery-dismiss">知道了</button></div></div>`:'')+(resetPending?`<section class="notice amber"><strong>重置 ${escape(state.case.id)}？</strong><p>将清空当前案例的草稿、报告和操作记录，其他场景保持原状。</p><div class="actions"><button class="button" id="reset-cancel">保留进度</button><button class="button" id="reset-confirm">确认重置本案例</button></div></section>`:'')+tourPanel()+(['overview','companion','copilot','evidence','delivery'].includes(id)?flowPanel():'')+({overview,companion,copilot,evidence,references:research,evaluation,delivery}[id])();bind();persist();}
$('#start-tour').onclick=startTour;
$('#reset').onclick=()=>{captureInputs();resetPending=true;render();};
window.addEventListener('hashchange',()=>{actionError='';captureInputs();render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',()=>{captureInputs();persist();});
if(!state.audit.length)log('载入演示场景','仅包含合成客户与资料');render();
